/* Bottom-left dock: a row of pills (Guide, and Agent on Structure) styled like the Audit button, and the open one's
   panel above them on the same frameless feathered black field as the audit trail, 300px wide like the checkpoint
   timeline in the opposite corner. Only one panel is open at a time. */
.dock {
  position: fixed; left: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 12;
  width: 300px; display: grid; gap: 12px; justify-items: start;
}
.dock-pills { display: flex; gap: 8px; }
.dock-pill {
  height: 32px; display: inline-flex; align-items: center; gap: 6px; padding: 0 14px 0 12px; border-radius: 99px;
  font-size: 13px; color: var(--ink-2); background: rgba(0, 0, 0, 0.6); border: 1px solid var(--hair);
  transition: color var(--fast), border-color var(--fast), background var(--fast);
}
.dock-pill:hover { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.04); }
.dock-pill[aria-expanded="true"] { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.06); }
.dock-live { width: 6px; height: 6px; margin-left: 2px; border-radius: 50%; background: var(--ink); animation: agent-pulse 1.4s ease-out infinite; }
.dock-body {
  justify-self: stretch; max-height: min(46vh, 420px); overflow-y: auto; padding: 12px 14px 14px; margin: -12px -14px 0;
  background: var(--field); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  --feather: linear-gradient(to right, transparent, #000 14px, #000 calc(100% - 14px), transparent), linear-gradient(to bottom, transparent, #000 12px, #000 calc(100% - 12px), transparent);
/* Page 4, Prioritize: the priority skyline's overlays. Same world as pages 1–3: true black, frameless instruments at
   the 24px edge, numerals lead, domain hues on the marks only, band by SHAPE (Must solid, Should outlined, Could a
   thin line), white = attention, sweep blue only for the PM's confirmed band. Reuses page 3's .dseg / .dlist / .dsheet. */

/* the scan's DOM labels stay gone, as on page 3 */
.scan[data-mode="prioritize"] :is(.ring-name, .ring-sub, .time-label, .ring-label, .theme-label, .area-label) { opacity: 0 !important; pointer-events: none; }
.scan[data-mode="prioritize"] ~ .dock .dock-body, .scan[data-mode="prioritize"] .dock-body { max-height: min(40vh, 340px); }

/* ------------------------------------------------------------------------------------------- band mark */
.pband { display: inline-block; flex: none; position: relative; width: 8px; height: 14px; --c: var(--ink-2); }
